'use strict';
const CURRICULUM_ID='grade4-term2-units1to4-v1';
const TOPICS=[{"id":"fraction","name":"분수의 덧셈과 뺄셈","short":"분수","icon":"½","color":"#e6f3b8","summary":"같은 크기의 조각을 더하고 빼요","concepts":[["분모가 같은 분수","분모는 똑같이 나눈 조각의 크기를 알려 줘요. 분모가 같은 분수를 더하거나 뺄 때는 분모를 그대로 두고 분자끼리 계산해요. 예: 2/7 + 3/7 = 5/7."],["1과 가분수","분자와 분모가 같으면 1이에요. 8/5는 5/5와 3/5로 나누어 1 3/5로 나타낼 수 있어요. 답을 약분하지 않아도 괜찮아요."],["대분수의 덧셈","자연수 부분끼리, 분수 부분끼리 더해요. 분수 부분이 1 이상이면 자연수로 옮겨요. 예: 1 4/5 + 2 3/5 = 4 2/5."],["대분수의 뺄셈","자연수 부분끼리, 분수 부분끼리 빼요. 분수 부분끼리 뺄 수 없으면 자연수 1을 분모만큼의 분자로 바꾸어요. 예: 3 1/5 = 2 6/5."],["자연수에서 분수 빼기","2를 1 5/5처럼 바꾸면 분수 부분을 뺄 수 있어요. 예: 2 − 3/5 = 1 2/5."],["문장 속 합과 차","함께 모은 양은 더하고, 쓰고 남은 양이나 두 양의 차는 빼요. 무엇을 구하는지와 분수의 기준이 되는 전체가 같은지 살펴봐요."]]},{"id":"triangle","name":"삼각형","short":"삼각형","icon":"△","color":"#dedff9","summary":"변의 길이와 각의 크기로 분류해요","concepts":[["이등변삼각형","두 변의 길이가 같은 삼각형이에요. 길이가 같은 두 변에 마주 보는 두 각의 크기도 같아요."],["정삼각형","세 변의 길이가 모두 같은 삼각형이에요. 세 각은 모두 60°예요. 이등변삼각형의 성질도 가지고 있어요."],["각으로 분류하기","세 각이 모두 예각이면 예각삼각형, 한 각이 직각이면 직각삼각형, 한 각이 둔각이면 둔각삼각형이에요. 가장 큰 각부터 확인하면 편해요."],["삼각형의 세 각","세 각의 크기의 합은 180°예요. 모르는 한 각은 180°에서 알고 있는 두 각의 크기를 빼서 구해요."],["같은 두 각 이용하기","이등변삼각형에서 같은 두 각의 합을 구한 뒤 2로 나누면 한 각의 크기를 알 수 있어요. 세 변이 같으면 세 각도 같아요."],["두 가지 분류 기준","변의 길이와 각의 크기는 서로 다른 기준이에요. 이등변삼각형이면서 직각삼각형일 수도 있어요. 그림을 돌려도 변과 각의 성질은 바뀌지 않아요."]]},{"id":"decimal","name":"소수의 덧셈과 뺄셈","short":"소수","icon":"0.1","color":"#d3efed","summary":"자릿값을 맞추어 정확하게 계산해요","concepts":[["소수 두 자리와 세 자리","소수 첫째 자리는 0.1, 둘째 자리는 0.01, 셋째 자리는 0.001의 자리예요. 0.36은 0.01이 36개인 수예요."],["소수의 크기 비교","자연수 부분부터 비교하고, 같으면 소수 첫째 자리, 둘째 자리 순서로 비교해요. 소수점 아래 숫자가 많다고 더 큰 수는 아니에요."],["끝에 붙인 0","소수의 오른쪽 끝에 0을 붙여도 크기는 같아요. 1.4와 1.40은 같은 수예요. 0.4와 0.04는 서로 다른 수예요."],["소수의 덧셈","소수점끼리 맞추어 같은 자리끼리 더해요. 0.01이 10개이면 0.1로, 0.1이 10개이면 1로 받아올려요."],["소수의 뺄셈","소수점끼리 맞추어 빼요. 같은 자리에서 뺄 수 없으면 왼쪽 자리에서 받아내려요. 3을 3.00으로 나타내면 계산하기 편해요."],["계산 결과 살펴보기","더한 결과가 각각의 양보다 작은지, 뺀 결과가 처음 양보다 큰지 살펴보며 실수를 찾아요. 단위도 끝에 확인해요."]]},{"id":"quad","name":"사각형","short":"사각형","icon":"▱","color":"#ffe9a9","summary":"수직·평행과 여러 사각형을 알아봐요","concepts":[["수직과 수선","두 직선이 만나 이루는 각이 직각이면 서로 수직이에요. 한 직선과 수직인 직선을 그 직선의 수선이라고 해요."],["평행과 평행선 사이 거리","같은 평면에서 아무리 늘여도 만나지 않는 두 직선은 평행해요. 평행선 사이의 거리는 두 직선을 수직으로 이은 선분의 길이이며, 어디서 재어도 같아요."],["사다리꼴과 평행사변형","마주 보는 한 쌍의 변이 평행한 사각형은 사다리꼴이에요. 두 쌍이 각각 평행하면 평행사변형이에요. 평행사변형은 사다리꼴의 조건도 만족해요."],["평행사변형과 마름모","평행사변형은 마주 보는 변의 길이와 각의 크기가 각각 같아요. 마름모는 네 변의 길이가 모두 같고, 마주 보는 변이 평행하며 마주 보는 각의 크기가 같아요."],["직사각형과 정사각형","네 각이 모두 직각이면 직사각형이에요. 네 변의 길이까지 모두 같으면 정사각형이에요. 정사각형은 직사각형과 마름모의 성질을 모두 가지고 있어요."],["사각형 사이의 관계","직사각형과 마름모는 모두 평행사변형이에요. 모든 직사각형이 정사각형인 것은 아니에요. 한 도형이 여러 사각형의 이름에 해당할 수도 있어요."]]}];
const QUESTION_TYPES=[{"id":"basic","name":"기본형","desc":"개념과 계산을 차근차근"},{"id":"application","name":"응용형","desc":"조건을 연결하여 한 단계 더"},{"id":"story","name":"서술형 · 문장제","desc":"이야기를 읽고 답은 간단하게"}];
